unsigned char far * far UncompressDACInstrument(unsigned char far *src,
                                                unsigned char far *dst,
                                                unsigned int length)
{
    unsigned char value;
    unsigned int i;
    struct DeltaTable table;

    value = 0x80;
    table = *(struct DeltaTable far *)src;
    src += 16;
    length >>= 1;
    for (i = 0; i < length; i++) {
        value += table.delta[src[i] >> 4];
        dst[2 * i] = value;
        value += table.delta[src[i] & 0xf];
        dst[2 * i + 1] = value;
    }
    return dst;
}
